INSERT OR IGNORE INTO "animes" ("id", "slug", "title_romaji", "title_english", "title_japanese", "synopsis", "cover_image", "banner_image", "type", "status", "season_name", "season_year", "episodes_count", "duration_per_ep", "rating", "is_featured", "is_trending", "sub_or_dub", "created_at", "updated_at") VALUES ('anime-16498', 'shingeki-no-kyojin', 'Shingeki no Kyojin', 'Attack on Titan', '進撃の巨人', 'Several hundred years ago, humans were nearly exterminated by titans. Titans are typically several stories tall, seem to have no intelligence, devour human beings and, worst of all, seem to do it for the pleasure rather than as a food source. A small percentage of humanity survived by walling themselves in a city protected by extremely high walls, even taller than the biggest of titans.
Flash forward to the present and the city has not seen a titan in over 100 years. Teenage boy Eren and his foster sister Mikasa witness something horrific as the city walls are destroyed by a colossal titan that appears out of thin air. As the smaller titans flood the city, the two kids watch in horror as their mother is eaten alive. Eren vows that he will murder every single titan and take revenge for all of mankind.
(Source: MangaHelpers)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx16498-buvcRTBx4NSm.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/16498-8jpFCOcDmneX.jpg', 'TV', 'Completed', 'Spring', 2013, 25, '24 min', 8.5, 1, 1, 'SUB', 1787750474777, 1787750474777);
INSERT OR IGNORE INTO "animes" ("id", "slug", "title_romaji", "title_english", "title_japanese", "synopsis", "cover_image", "banner_image", "type", "status", "season_name", "season_year", "episodes_count", "duration_per_ep", "rating", "is_featured", "is_trending", "sub_or_dub", "created_at", "updated_at") VALUES ('anime-101922', 'kimetsu-no-yaiba', 'Kimetsu no Yaiba', 'Demon Slayer: Kimetsu no Yaiba', '鬼滅の刃', 'It is the Taisho Period in Japan. Tanjiro, a kindhearted boy who sells charcoal for a living, finds his family slaughtered by a demon. To make matters worse, his younger sister Nezuko, the sole survivor, has been transformed into a demon herself. Though devastated by this grim reality, Tanjiro resolves to become a “demon slayer” so that he can turn his sister back into a human, and kill the demon that massacred his family.

(Source: Crunchyroll)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101922-WBsBl0ClmgYL.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101922-33MtJGsUSxga.jpg', 'TV', 'Completed', 'Spring', 2019, 26, '24 min', 8.3, 1, 1, 'SUB', 1787750474778, 1787750474778);
INSERT OR IGNORE INTO "animes" ("id", "slug", "title_romaji", "title_english", "title_japanese", "synopsis", "cover_image", "banner_image", "type", "status", "season_name", "season_year", "episodes_count", "duration_per_ep", "rating", "is_featured", "is_trending", "sub_or_dub", "created_at", "updated_at") VALUES ('anime-113415', 'jujutsu-kaisen', 'Jujutsu Kaisen', 'JUJUTSU KAISEN', '呪術廻戦', 'A boy fights... for "the right death."

Hardship, regret, shame: the negative feelings that humans feel become Curses that lurk in our everyday lives. The Curses run rampant throughout the world, capable of leading people to terrible misfortune and even death. What''s more, the Curses can only be exorcised by another Curse.

Itadori Yuji is a boy with tremendous physical strength, though he lives a completely ordinary high school life. One day, to save a friend who has been attacked by Curses, he eats the finger of the Double-Faced Specter, taking the Curse into his own soul. From then on, he shares one body with the Double-Faced Specter. Guided by the most powerful of sorcerers, Gojou Satoru, Itadori is admitted to the Tokyo Metropolitan Technical High School of Sorcery, an organization that fights the Curses... and thus begins the heroic tale of a boy who became a Curse to exorcise a Curse, a life from which he could never turn back.

(Source: Crunchyroll)

Note: The first episode received an early web premiere on September 19th, 2020. The regular TV broadcast started on October 3rd, 2020.', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx113415-LHBAeoZDIsnF.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/113415-jQBSkxWAAk83.jpg', 'TV', 'Completed', 'Fall', 2020, 24, '24 min', 8.4, 1, 1, 'SUB', 1787750474778, 1787750474778);
INSERT OR IGNORE INTO "animes" ("id", "slug", "title_romaji", "title_english", "title_japanese", "synopsis", "cover_image", "banner_image", "type", "status", "season_name", "season_year", "episodes_count", "duration_per_ep", "rating", "is_featured", "is_trending", "sub_or_dub", "created_at", "updated_at") VALUES ('anime-1535', 'death-note', 'DEATH NOTE', 'Death Note', 'DEATH NOTE', 'Light Yagami is a genius high school student who is about to learn about life through a book of death. When a bored shinigami, a God of Death, named Ryuk drops a black notepad called a Death Note, Light receives power over life and death with the stroke of a pen. Determined to use this dark gift for the best, Light sets out to rid the world of evil… namely, the people he believes to be evil. Should anyone hold such power?

The consequences of Light’s actions will set the world ablaze.

(Source: VIZ Media)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1535-kUgkcrfOrkUM.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1535.jpg', 'TV', 'Completed', 'Fall', 2006, 37, '23 min', 8.4, 1, 1, 'SUB', 1787750474778, 1787750474778);
INSERT OR IGNORE INTO "animes" ("id", "slug", "title_romaji", "title_english", "title_japanese", "synopsis", "cover_image", "banner_image", "type", "status", "season_name", "season_year", "episodes_count", "duration_per_ep", "rating", "is_featured", "is_trending", "sub_or_dub", "created_at", "updated_at") VALUES ('anime-21459', 'boku-no-hero-academia', 'Boku no Hero Academia', 'My Hero Academia', '僕のヒーローアカデミア', 'What would the world be like if 80 percent of the population manifested extraordinary superpowers called “Quirks” at age four? Heroes and villains would be battling it out everywhere! Becoming a hero would mean learning to use your power, but where would you go to study? U.A. High''s Hero Program of course! But what would you do if you were one of the 20 percent who were born Quirkless?

Middle school student Izuku Midoriya wants to be a hero more than anything, but he hasn''t got an ounce of power in him. With no chance of ever getting into the prestigious U.A. High School for budding heroes, his life is looking more and more like a dead end. Then an encounter with All Might, the greatest hero of them all gives him a chance to change his destiny…

(Source: VIZ Media)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21459-nYh85uj2Fuwr.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21459-yeVkolGKdGUV.jpg', 'TV', 'Completed', 'Spring', 2016, 13, '24 min', 7.7, 1, 1, 'SUB', 1787750474778, 1787750474778);
INSERT OR IGNORE INTO "animes" ("id", "slug", "title_romaji", "title_english", "title_japanese", "synopsis", "cover_image", "banner_image", "type", "status", "season_name", "season_year", "episodes_count", "duration_per_ep", "rating", "is_featured", "is_trending", "sub_or_dub", "created_at", "updated_at") VALUES ('anime-11061', 'hunterhunter-2011', 'HUNTER×HUNTER (2011)', 'Hunter x Hunter (2011)', 'HUNTER×HUNTER (2011)', 'A new adaption of the manga of the same name by Togashi Yoshihiro.
A Hunter is one who travels the world doing all sorts of dangerous tasks. From capturing criminals to searching deep within uncharted lands for any lost treasures. Gon is a young boy whose father disappeared long ago, being a Hunter. He believes if he could also follow his father''s path, he could one day reunite with him.
After becoming 12, Gon leaves his home and takes on the task of entering the Hunter exam, notorious for its low success rate and high probability of death to become an official Hunter. He befriends the revenge-driven Kurapika, the doctor-to-be Leorio and the rebellious ex-assassin Killua in the exam, with their friendship prevailing throughout the many trials and threats they come upon taking on the dangerous career of a Hunter.', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx11061-y5gsT1hoHuHw.png', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/11061-8WkkTZ6duKpq.jpg', 'TV', 'Completed', 'Fall', 2011, 148, '24 min', 8.9, 0, 1, 'SUB', 1787750474778, 1787750474778);
INSERT OR IGNORE INTO "animes" ("id", "slug", "title_romaji", "title_english", "title_japanese", "synopsis", "cover_image", "banner_image", "type", "status", "season_name", "season_year", "episodes_count", "duration_per_ep", "rating", "is_featured", "is_trending", "sub_or_dub", "created_at", "updated_at") VALUES ('anime-21087', 'one-punch-man', 'One Punch Man', 'One-Punch Man', 'ワンパンマン', 'Saitama has a rather peculiar hobby, being a superhero, but despite his heroic deeds and superhuman abilities, a shadow looms over his life. He''s become much too powerful, to the point that every opponent ends up defeated with a single punch.

The lack of challenge has driven him into a state of apathy, as he watches his life pass by having lost all enthusiasm, at least until he''s unwillingly thrust in the role of being a mentor to the young and revenge-driven Genos.', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21087-B5DHjqZ3kW4b.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21087-sHb9zUZFsHe1.jpg', 'TV', 'Completed', 'Fall', 2015, 12, '24 min', 8.3, 0, 1, 'SUB', 1787750474778, 1787750474778);
INSERT OR IGNORE INTO "animes" ("id", "slug", "title_romaji", "title_english", "title_japanese", "synopsis", "cover_image", "banner_image", "type", "status", "season_name", "season_year", "episodes_count", "duration_per_ep", "rating", "is_featured", "is_trending", "sub_or_dub", "created_at", "updated_at") VALUES ('anime-21', 'one-piece', 'ONE PIECE', 'ONE PIECE', 'ONE PIECE', 'Gold Roger was known as the Pirate King, the strongest and most infamous being to have sailed the Grand Line. The capture and death of Roger by the World Government brought a change throughout the world. His last words before his death revealed the location of the greatest treasure in the world, One Piece. It was this revelation that brought about the Grand Age of Pirates, men who dreamed of finding One Piece (which promises an unlimited amount of riches and fame), and quite possibly the most coveted of titles for the person who found it, the title of the Pirate King.
Enter Monkey D. Luffy, a 17-year-old boy that defies your standard definition of a pirate. Rather than the popular persona of a wicked, hardened, toothless pirate who ransacks villages for fun, Luffy’s reason for being a pirate is one of pure wonder; the thought of an exciting adventure and meeting new and intriguing people, along with finding One Piece, are his reasons of becoming a pirate. Following in the footsteps of his childhood hero, Luffy and his crew travel across the Grand Line, experiencing crazy adventures, unveiling dark mysteries and battling strong enemies, all in order to reach One Piece.
*This includes the following special episodes:
- Chopperman to the Rescue! Protect the TV Station by the Shore! (Episode 336)
- The Strongest Tag-Team! Luffy and Toriko''s Hard Struggle! (Episode 492)
- Team Formation! Save Chopper (Episode 542)
- History''s Strongest Collaboration vs. Glutton of the Sea (Episode 590)
- 20th Anniversary! Special Romance Dawn (Episode 907)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21-ELSYx3yMPcKM.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21-wf37VakJmZqs.jpg', 'TV', 'Ongoing', 'Fall', 1999, 12, '24 min', 8.7, 0, 1, 'SUB', 1787750474778, 1787750474778);
INSERT OR IGNORE INTO "animes" ("id", "slug", "title_romaji", "title_english", "title_japanese", "synopsis", "cover_image", "banner_image", "type", "status", "season_name", "season_year", "episodes_count", "duration_per_ep", "rating", "is_featured", "is_trending", "sub_or_dub", "created_at", "updated_at") VALUES ('anime-20605', 'tokyo-ghoul', 'Tokyo Ghoul', 'Tokyo Ghoul', '東京喰種 トーキョーグール', 'The suspense horror/dark fantasy story is set in Tokyo, which is haunted by mysterious "ghouls" who are devouring humans. People are gripped by the fear of these ghouls whose identities are masked in mystery. An ordinary college student named Kaneki encounters Rize, a girl who is an avid reader like him, at the café he frequents. Little does he realize that his fate will change overnight.

(Source: Anime News Network)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b20605-k665mVkSug8D.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20605-RCJ7M71zLmrh.jpg', 'TV', 'Completed', 'Summer', 2014, 12, '24 min', 7.6, 0, 1, 'SUB', 1787750474779, 1787750474779);
INSERT OR IGNORE INTO "animes" ("id", "slug", "title_romaji", "title_english", "title_japanese", "synopsis", "cover_image", "banner_image", "type", "status", "season_name", "season_year", "episodes_count", "duration_per_ep", "rating", "is_featured", "is_trending", "sub_or_dub", "created_at", "updated_at") VALUES ('anime-20958', 'shingeki-no-kyojin-season-2', 'Shingeki no Kyojin Season 2', 'Attack on Titan Season 2', '進撃の巨人 Season２', 'Eren Jaeger swore to wipe out every last Titan, but in a battle for his life he wound up becoming the thing he hates most. With his new powers, he fights for humanity''s freedom facing the monsters that threaten his home. After a bittersweet victory against the Female Titan, Eren finds no time to rest—a horde of Titans is approaching Wall Rose and the battle for humanity continues!

(Source: Funimation)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20958-HuFJyr54Mmir.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20958-Y7eQdz9VENBD.jpg', 'TV', 'Completed', 'Spring', 2017, 12, '25 min', 8.5, 0, 1, 'SUB', 1787750474779, 1787750474779);
INSERT OR IGNORE INTO "animes" ("id", "slug", "title_romaji", "title_english", "title_japanese", "synopsis", "cover_image", "banner_image", "type", "status", "season_name", "season_year", "episodes_count", "duration_per_ep", "rating", "is_featured", "is_trending", "sub_or_dub", "created_at", "updated_at") VALUES ('anime-5114', 'hagane-no-renkinjutsushi-fullmetal-alchemist', 'Hagane no Renkinjutsushi: FULLMETAL ALCHEMIST', 'Fullmetal Alchemist: Brotherhood', '鋼の錬金術師 FULLMETAL ALCHEMIST', '"In order for something to be obtained, something of equal value must be lost."

Alchemy is bound by this Law of Equivalent Exchange—something the young brothers Edward and Alphonse Elric only realize after attempting human transmutation: the one forbidden act of alchemy. They pay a terrible price for their transgression—Edward loses his left leg, Alphonse his physical body. It is only by the desperate sacrifice of Edward''s right arm that he is able to affix Alphonse''s soul to a suit of armor. Devastated and alone, it is the hope that they would both eventually return to their original bodies that gives Edward the inspiration to obtain metal limbs called "automail" and become a state alchemist, the Fullmetal Alchemist.

Three years of searching later, the brothers seek the Philosopher''s Stone, a mythical relic that allows an alchemist to overcome the Law of Equivalent Exchange. Even with military allies Colonel Roy Mustang, Lieutenant Riza Hawkeye, and Lieutenant Colonel Maes Hughes on their side, the brothers find themselves caught up in a nationwide conspiracy that leads them not only to the true nature of the elusive Philosopher''s Stone, but their country''s murky history as well. In between finding a serial killer and racing against time, Edward and Alphonse must ask themselves if what they are doing will make them human again... or take away their humanity.

(Source: MAL Rewrite)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx5114-nSWCgQlmOMtj.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/5114-q0V5URebphSG.jpg', 'TV', 'Completed', 'Spring', 2009, 64, '25 min', 9, 0, 1, 'SUB', 1787750474779, 1787750474779);
INSERT OR IGNORE INTO "animes" ("id", "slug", "title_romaji", "title_english", "title_japanese", "synopsis", "cover_image", "banner_image", "type", "status", "season_name", "season_year", "episodes_count", "duration_per_ep", "rating", "is_featured", "is_trending", "sub_or_dub", "created_at", "updated_at") VALUES ('anime-20', 'naruto', 'NARUTO', 'Naruto', 'NARUTO -ナルト-', 'Naruto Uzumaki, a hyperactive and knuckle-headed ninja, lives in Konohagakure, the Hidden Leaf village. Moments prior to his birth, a huge demon known as the Kyuubi, the Nine-tailed Fox, attacked Konohagakure and wreaked havoc. In order to put an end to the Kyuubi''s rampage, the leader of the village, the 4th Hokage, sacrificed his life and sealed the monstrous beast inside the newborn Naruto. 
Shunned because of the presence of the Kyuubi inside him, Naruto struggles to find his place in the village. He strives to become the Hokage of Konohagakure, and he meets many friends and foes along the way. 
(Source: MAL Rewrite)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20-dE6UHbFFg1A5.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20-HHxhPj5JD13a.jpg', 'TV', 'Completed', 'Fall', 2002, 220, '23 min', 8, 0, 1, 'SUB', 1787750474779, 1787750474779);
INSERT OR IGNORE INTO "animes" ("id", "slug", "title_romaji", "title_english", "title_japanese", "synopsis", "cover_image", "banner_image", "type", "status", "season_name", "season_year", "episodes_count", "duration_per_ep", "rating", "is_featured", "is_trending", "sub_or_dub", "created_at", "updated_at") VALUES ('anime-11757', 'sword-art-online', 'Sword Art Online', 'Sword Art Online', 'ソードアート・オンライン', 'In the near future, a Virtual Reality Massive Multiplayer Online Role-Playing Game (VRMMORPG) called Sword Art Online has been released where players control their avatars with their bodies using a piece of technology called Nerve Gear. One day, players discover they cannot log out, as the game creator is holding them captive unless they reach the 100th floor of the game''s tower and defeat the final boss. However, if they die in the game, they die in real life. Their struggle for survival starts now...
(Source: Crunchyroll)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx11757-SxYDUzdr9rh2.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/11757-TlEEV9weG4Ag.jpg', 'TV', 'Completed', 'Summer', 2012, 25, '23 min', 7, 0, 1, 'SUB', 1787750474779, 1787750474779);
INSERT OR IGNORE INTO "animes" ("id", "slug", "title_romaji", "title_english", "title_japanese", "synopsis", "cover_image", "banner_image", "type", "status", "season_name", "season_year", "episodes_count", "duration_per_ep", "rating", "is_featured", "is_trending", "sub_or_dub", "created_at", "updated_at") VALUES ('anime-20954', 'koe-no-katachi', 'Koe no Katachi', 'A Silent Voice', '聲の形', 'After transferring into a new school, a deaf girl, Shouko Nishimiya, is bullied by the popular Shouya Ishida. As Shouya continues to bully Shouko, the class turns its back on him. Shouko transfers and Shouya grows up as an outcast. Alone and depressed, the regretful Shouya finds Shouko to make amends.

(Source: Eleven Arts)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20954-sYRfE5jQRtSB.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20954-f30bHMXa5Qoe.jpg', 'Movie', 'Completed', 'Summer', 2016, 1, '130 min', 8.8, 0, 1, 'SUB', 1787750474779, 1787750474779);
INSERT OR IGNORE INTO "animes" ("id", "slug", "title_romaji", "title_english", "title_japanese", "synopsis", "cover_image", "banner_image", "type", "status", "season_name", "season_year", "episodes_count", "duration_per_ep", "rating", "is_featured", "is_trending", "sub_or_dub", "created_at", "updated_at") VALUES ('anime-21519', 'kimi-no-na-wa', 'Kimi no Na wa.', 'Your Name.', '君の名は。', 'Mitsuha Miyamizu, a high school girl, yearns to live the life of a boy in the bustling city of Tokyo—a dream that stands in stark contrast to her present life in the countryside. Meanwhile in the city, Taki Tachibana lives a busy life as a high school student while juggling his part-time job and hopes for a future in architecture.

One day, Mitsuha awakens in a room that is not her own and suddenly finds herself living the dream life in Tokyo—but in Taki''s body! Elsewhere, Taki finds himself living Mitsuha''s life in the humble countryside. In pursuit of an answer to this strange phenomenon, they begin to search for one another.

Kimi no Na wa. revolves around Mitsuha and Taki''s actions, which begin to have a dramatic impact on each other''s lives, weaving them into a fabric held together by fate and circumstance.

(Source: MAL Rewrite)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21519-SUo3ZQuCbYhJ.png', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21519-1ayMXgNlmByb.jpg', 'Movie', 'Completed', 'Summer', 2016, 1, '107 min', 8.6, 0, 1, 'SUB', 1787750474779, 1787750474779);
INSERT OR IGNORE INTO "animes" ("id", "slug", "title_romaji", "title_english", "title_japanese", "synopsis", "cover_image", "banner_image", "type", "status", "season_name", "season_year", "episodes_count", "duration_per_ep", "rating", "is_featured", "is_trending", "sub_or_dub", "created_at", "updated_at") VALUES ('anime-99147', 'shingeki-no-kyojin-season-3', 'Shingeki no Kyojin Season 3', 'Attack on Titan Season 3', '進撃の巨人 Season３', 'Eren and his companions in the 104th are assigned to the newly-formed Levi Squad, whose assignment is to keep Eren and Historia safe given Eren''s newly-discovered power and Historia''s knowledge and pedigree. Levi and Erwin have good reason to be concerned, because the priest of the Church that Hanji had hidden away was found tortured to death, making it clear that the Military Police are involved with the cover-up. Things get more harrowing when the MPs make a move on Erwin and the Levi Squad narrowly avoids capture. Eren is also having problems with his Titan transformation, and a deadly killer has been hired to secure Eren and Historia, one Levi knows all too well from his youth.

(Source: Anime News Network)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx99147-AiPDD8cwlCfi.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/99147-HACsFVrynFf5.jpg', 'TV', 'Completed', 'Summer', 2018, 12, '24 min', 8.6, 0, 1, 'SUB', 1787750474779, 1787750474779);
INSERT OR IGNORE INTO "animes" ("id", "slug", "title_romaji", "title_english", "title_japanese", "synopsis", "cover_image", "banner_image", "type", "status", "season_name", "season_year", "episodes_count", "duration_per_ep", "rating", "is_featured", "is_trending", "sub_or_dub", "created_at", "updated_at") VALUES ('anime-21856', 'boku-no-hero-academia-2', 'Boku no Hero Academia 2', 'My Hero Academia Season 2', '僕のヒーローアカデミア２', 'Taking off right after the last episode of the first season. The school is temporarily closed due to security. When U.A. restarts, it is announced that the highly anticipated School Sports Festival will soon be taking place. All classes: Hero, Support, General and Business will be participating. Tournaments all round will decide who is the top Hero in training.(Source: Anime News Network)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21856-gutauxhWAwn6.png', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21856-wtSHgeHFmzdG.jpg', 'TV', 'Completed', 'Spring', 2017, 25, '24 min', 7.9, 0, 1, 'SUB', 1787750474779, 1787750474779);
INSERT OR IGNORE INTO "animes" ("id", "slug", "title_romaji", "title_english", "title_japanese", "synopsis", "cover_image", "banner_image", "type", "status", "season_name", "season_year", "episodes_count", "duration_per_ep", "rating", "is_featured", "is_trending", "sub_or_dub", "created_at", "updated_at") VALUES ('anime-110277', 'shingeki-no-kyojin-the-final-season', 'Shingeki no Kyojin: The Final Season', 'Attack on Titan Final Season', '進撃の巨人 The Final Season', 'It’s been four years since the Scout Regiment reached the shoreline, and the world looks different now. Things are heating up as the fate of the Scout Regiment—and the people of Paradis—are determined at last. However, Eren is missing. Will he reappear before age-old tensions between Marleyans and Eldians result in the war of all wars?

(Source: Crunchyroll)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx110277-sKUNXAsWMNFw.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/110277-iuGn6F5bK1U1.jpg', 'TV', 'Completed', 'Winter', 2021, 16, '24 min', 8.7, 0, 1, 'SUB', 1787750474779, 1787750474779);
INSERT OR IGNORE INTO "animes" ("id", "slug", "title_romaji", "title_english", "title_japanese", "synopsis", "cover_image", "banner_image", "type", "status", "season_name", "season_year", "episodes_count", "duration_per_ep", "rating", "is_featured", "is_trending", "sub_or_dub", "created_at", "updated_at") VALUES ('anime-101759', 'yakusoku-no-neverland', 'Yakusoku no Neverland', 'The Promised Neverland', '約束のネバーランド', 'Emma, Norman and Ray are the brightest kids at the Grace Field House orphanage. And under the care of the woman they refer to as “Mom,” all the kids have enjoyed a comfortable life. Good food, clean clothes and the perfect environment to learn—what more could an orphan ask for? One day, though, Emma and Norman uncover the dark truth of the outside world they are forbidden from seeing.

(Source: VIZ Media)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101759-8UR7r9MNVpz2.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101759-MhlCoeqnODso.jpg', 'TV', 'Completed', 'Winter', 2019, 12, '23 min', 8.3, 0, 1, 'SUB', 1787750474779, 1787750474779);
INSERT OR IGNORE INTO "animes" ("id", "slug", "title_romaji", "title_english", "title_japanese", "synopsis", "cover_image", "banner_image", "type", "status", "season_name", "season_year", "episodes_count", "duration_per_ep", "rating", "is_featured", "is_trending", "sub_or_dub", "created_at", "updated_at") VALUES ('anime-127230', 'chainsaw-man', 'Chainsaw Man', 'Chainsaw Man', 'チェンソーマン', 'Denji is a teenage boy living with a Chainsaw Devil named Pochita. Due to the debt his father left behind, he has been living a rock-bottom life while repaying his debt by harvesting devil corpses with Pochita.
One day, Denji is betrayed and killed. As his consciousness fades, he makes a contract with Pochita and gets revived as "Chainsaw Man" — a man with a devil''s heart.

(Source: Crunchyroll)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx127230-DdP4vAdssLoz.png', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/127230-o8IRwCGVr9KW.jpg', 'TV', 'Completed', 'Fall', 2022, 12, '25 min', 8.3, 0, 1, 'SUB', 1787750474779, 1787750474779);

